import random
random.seed(123)

n_cliques = 10
n_vertices = 30
n_edges = 57

# Build adjacency
edges = []
for g in range(n_cliques):
    for i in range(3):
        for j in range(i+1, 3):
            edges.append((g*3 + i, g*3 + j))
for g in range(n_cliques - 1):
    for i in range(3):
        edges.append((g*3 + i, (g+1)*3 + i))

# For each vertex, track which labels are still available
# For each edge, track which differences are still available

def solve_backtrack():
    """Backtracking search with constraint propagation"""

    # Order vertices by degree (most constrained first)
    degree = [0] * n_vertices
    for u, v in edges:
        degree[u] += 1
        degree[v] += 1

    # Sort vertices by degree (descending)
    vertex_order = sorted(range(n_vertices), key=lambda v: -degree[v])

    labels = [None] * n_vertices
    used_labels = set()
    used_diffs = set()

    def is_valid(vertex, label):
        """Check if assigning label to vertex is valid"""
        if label in used_labels:
            return False
        for u, v in edges:
            if u == vertex and labels[v] is not None:
                d = abs(label - labels[v])
                if d in used_diffs or d == 0:
                    return False
            elif v == vertex and labels[u] is not None:
                d = abs(labels[u] - label)
                if d in used_diffs or d == 0:
                    return False
        return True

    def assign(vertex, label):
        labels[vertex] = label
        used_labels.add(label)
        for u, v in edges:
            if u == vertex and labels[v] is not None:
                used_diffs.add(abs(label - labels[v]))
            elif v == vertex and labels[u] is not None:
                used_diffs.add(abs(labels[u] - label))

    def unassign(vertex, label):
        labels[vertex] = None
        used_labels.remove(label)
        for u, v in edges:
            if u == vertex and labels[v] is not None:
                used_diffs.remove(abs(label - labels[v]))
            elif v == vertex and labels[u] is not None:
                used_diffs.remove(abs(labels[u] - label))

    def backtrack(idx):
        if idx == n_vertices:
            return True

        vertex = vertex_order[idx]

        # Try labels in a smart order
        # Try extreme values first (0, 57, 1, 56, ...)
        candidates = list(range(58))
        random.shuffle(candidates)

        for label in candidates:
            if is_valid(vertex, label):
                assign(vertex, label)
                if backtrack(idx + 1):
                    return True
                unassign(vertex, label)

        return False

    if backtrack(0):
        return labels
    return None

# This might be too slow, let's try a different approach
# Use simulated annealing or tabu search

def solve_simulated_annealing():
    """Simulated annealing approach"""

    # Start with a random permutation
    labels = random.sample(range(58), 30)

    def energy(labels):
        """Number of edge label collisions"""
        diffs = {}
        collisions = 0
        for u, v in edges:
            d = abs(labels[u] - labels[v])
            if d in diffs:
                collisions += 1
            diffs[d] = diffs.get(d, 0) + 1
        return collisions

    best_labels = labels[:]
    best_energy = energy(labels)

    temp = 1000
    cooling_rate = 0.9995

    for iteration in range(500000):
        if best_energy == 0:
            print(f"Found solution at iteration {iteration}!")
            return best_labels

        # Swap two random labels
        i, j = random.sample(range(30), 2)
        new_labels = labels[:]
        new_labels[i], new_labels[j] = new_labels[j], new_labels[i]

        new_energy = energy(new_labels)
        delta = new_energy - best_energy

        if new_energy < best_energy:
            best_labels = new_labels[:]
            best_energy = new_energy
            labels = new_labels
        elif random.random() < 0.01:  # Accept worse solutions with small probability
            labels = new_labels

        temp *= cooling_rate

        if iteration % 50000 == 0:
            print(f"Iteration {iteration}, best energy: {best_energy}")

    print(f"Best energy after SA: {best_energy}")
    return best_labels if best_energy == 0 else None

result = solve_simulated_annealing()
